package org.jlinalg.cli;

import java.nio.file.*;
import java.util.*;
import org.jlinalg.sequence.LeafCutterClusters;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Test-only actual-JAR driver; component success is not a complete LeafCutter workflow. */
public final class LeafCutterClustersMatrix {
    private LeafCutterClustersMatrix() { }
    private static Map<String,Object> counted(LeafCutterClusters.Counted c){return Map.of("chromosome",c.intron().axis().chromosome(),"strand",c.intron().axis().strand(),"start",c.intron().start(),"end",c.intron().end(),"reads",c.reads());}
    private static Map<String,Object> cluster(LeafCutterClusters.Cluster c){return Map.of("ordinal",c.ordinal(),"axis",List.of(c.axis().chromosome(),c.axis().strand()),"introns",c.introns().stream().map(LeafCutterClustersMatrix::counted).toList());}
    private static Map<String,Object> quantified(LeafCutterClusters.Quantified r){return Map.of("id",r.id(),"chromosome",r.intron().axis().chromosome(),"strand",r.intron().axis().strand(),"start",r.intron().start(),"end",r.intron().end(),"cluster",r.cluster(),"numerators",r.numerators(),"denominators",r.denominators());}
    private static Map<String,Object> result(LeafCutterClusters.Result r){return Map.of("samples",r.samples(),"pooled",r.pooled().stream().map(LeafCutterClustersMatrix::cluster).toList(),"refined",r.refined().stream().map(LeafCutterClustersMatrix::cluster).toList(),"rows",r.rows().stream().map(LeafCutterClustersMatrix::quantified).toList(),"input_dispositions",r.inputDispositions().stream().map(x->Map.of("sample",x.sampleOrdinal(),"row",x.rowOrdinal(),"original_line",x.source().originalLine(),"disposition",x.disposition().name())).toList(),"overlap_clusters_scanned",r.overlapClustersScanned(),"warnings",r.warnings());}
    private static long number(Object value,long minimum,long maximum)throws Exception {return integer(value,minimum,maximum);}
    public static void main(String[] args)throws Exception {
        require(args.length==2,"Need complete cases.json and NEW output directory");Path request=Path.of(args[0]),out=Path.of(args[1]);byte[] raw=NextflowFiles.bytes(request,16777216);var fixture=object(NextflowParameters.parse(NextflowFiles.utf8(raw),16777216,2000000));require(!Files.exists(out),"Existing native result directory protected");Files.createDirectory(out);var reports=new ArrayList<Object>();
        for(Object item:list(fixture.get("cases"))){var c=object(item);String id=text(c.get("id"));require(id.matches("[a-z0-9-]+"),"Unsafe literal case ID");var op=object(c.get("options"));var capacity=object(c.get("limits"));var limits=new LeafCutterClusters.Limits(Math.toIntExact(integer(capacity.get("maximum_samples"),1,1000000)),number(capacity.get("maximum_input_rows"),1,1000000000),number(capacity.get("maximum_distinct_introns"),1,1000000000),number(capacity.get("maximum_work"),1,Long.MAX_VALUE),number(capacity.get("maximum_output_cells"),1,Long.MAX_VALUE));var options=new LeafCutterClusters.Options(number(op.get("maximum_intron_length"),1,Long.MAX_VALUE),number(op.get("minimum_reads"),0,Long.MAX_VALUE),Double.parseDouble(NextflowJson.json(op.get("minimum_ratio"))),bool(op.get("check_chromosomes")));var samples=new ArrayList<LeafCutterClusters.Sample>();
            for(Object sample:list(c.get("samples"))){var s=object(sample);var rows=new ArrayList<LeafCutterClusters.Input>();for(Object line:list(s.get("lines")))rows.add(LeafCutterClusters.parseRegtools(text(line)));samples.add(new LeafCutterClusters.Sample(text(s.get("id")),rows));}
            var answer=LeafCutterClusters.compute(samples,options,limits);NextflowFiles.writeJson(out.resolve(id+".json"),result(answer));reports.add(Map.of("id",id,"rows",answer.rows().size(),"refined_clusters",answer.refined().size()));
        }
        var rejections=new ArrayList<String>();String good="chr1\t92\t207\tj\t30\t+\t92\t207\t0\t2\t8,8\t0,107";var base=new LeafCutterClusters.Sample("S",List.of(LeafCutterClusters.parseRegtools(good),LeafCutterClusters.parseRegtools(good.replace("207","307"))));var option=new LeafCutterClusters.Options(100000,3,.001,true);var lim=LeafCutterClusters.Limits.defaults();
        reject("negative-read-count",()->LeafCutterClusters.parseRegtools(good.replace("\tj\t30\t","\tj\t-1\t")),rejections);reject("negative-coordinate",()->LeafCutterClusters.parseRegtools(good.replace("\t92\t","\t-1\t")),rejections);reject("missing-field",()->LeafCutterClusters.parseRegtools("chr1 0 10 j 3 +"),rejections);reject("extra-field",()->LeafCutterClusters.parseRegtools(good+" extra"),rejections);reject("trailing-block-comma",()->LeafCutterClusters.parseRegtools(good.replace("8,8","8,8,")),rejections);reject("colon-contig",()->LeafCutterClusters.parseRegtools(good.replace("chr1","chr1:alt")),rejections);reject("coordinate-overflow",()->LeafCutterClusters.parseRegtools(good.replace("\t92\t207\t","\t9223372036854775800\t9223372036854775807\t")),rejections);reject("count-overflow",()->LeafCutterClusters.compute(List.of(new LeafCutterClusters.Sample("S",List.of(LeafCutterClusters.parseRegtools(good.replace("\tj\t30\t","\tj\t9223372036854775807\t")),LeafCutterClusters.parseRegtools(good)))),option,lim),rejections);reject("empty-sample-family",()->LeafCutterClusters.compute(List.of(),option,lim),rejections);reject("sample-capacity",()->LeafCutterClusters.compute(List.of(base,base),option,new LeafCutterClusters.Limits(1,10,10,10000,100)),rejections);reject("source-row-capacity",()->LeafCutterClusters.compute(List.of(base),option,new LeafCutterClusters.Limits(10,1,10,10000,100)),rejections);reject("distinct-intron-capacity",()->LeafCutterClusters.compute(List.of(base),option,new LeafCutterClusters.Limits(10,10,1,10000,100)),rejections);reject("work-capacity",()->LeafCutterClusters.compute(List.of(base),option,new LeafCutterClusters.Limits(10,10,10,1,100)),rejections);reject("complete-output-capacity",()->LeafCutterClusters.compute(List.of(base),option,new LeafCutterClusters.Limits(10,10,10,10000,1)),rejections);reject("NaN-ratio",()->new LeafCutterClusters.Options(100000,3,Double.NaN,true),rejections);reject("infinite-ratio",()->new LeafCutterClusters.Options(100000,3,Double.POSITIVE_INFINITY,true),rejections);reject("zero-length-limit",()->new LeafCutterClusters.Options(0,3,.001,true),rejections);
        require(Arrays.equals(raw,NextflowFiles.bytes(request,16777216)),"Complete original fixture changed during native evaluation");NextflowFiles.writeJson(out.resolve("COMPLETED.json"),Map.of("status","PASS_NATIVE_LEAFCUTTER_CLUSTER_COMPONENT_CASES_ONLY","cases",reports,"expected_native_rejections",rejections,"implementation_credit",false,"whole_goal_complete",false));System.out.println("Native LeafCutter cluster component: "+reports.size()+" cases; "+rejections.size()+" expected rejections; full tool unadmitted");
    }
    @FunctionalInterface private interface Check {Object run()throws Exception;}
    private static void reject(String name,Check check,List<String> results)throws Exception {boolean rejected=false;try{check.run();}catch(IllegalArgumentException|ArithmeticException expected){rejected=true;}require(rejected,"Native invalid/capacity input unexpectedly admitted: "+name);results.add(name);}
}
